if not bak.exists():
    bak.write_text(s)
anchor = '''    # Optional cube center visual logging.\n'''
block = '''    # Optional after-grasp fixed joint-space macro. Default off.\n    # This is for real-robot debugging when ACT can grasp but falls back into\n    # repeated grasp attempts instead of transporting/releasing. It only starts\n    # after the first close permission has occurred.\n    after_grasp_macro = os.environ.get("ROLLOUT_AFTER_GRASP_MACRO", "").strip().lower()\n    if after_grasp_macro == "fixed_place":\n        if bool(locals().get("allow_close", False)) and not getattr(send_next_action, "_codex_after_grasp_macro_started", False):\n            send_next_action._codex_after_grasp_macro_started = True\n            send_next_action._codex_after_grasp_macro_frame = 0\n        if getattr(send_next_action, "_codex_after_grasp_macro_started", False):\n            frame = int(getattr(send_next_action, "_codex_after_grasp_macro_frame", 0) or 0)\n            send_next_action._codex_after_grasp_macro_frame = frame + 1\n\n            # Conservative macro values are kept within poses already observed\n            # from ACT rollout logs on this robot/checkpoint.\n            close_g = float(os.environ.get("ROLLOUT_AFTER_GRASP_CLOSE_VALUE", "3") or 3)\n            open_g = float(os.environ.get("ROLLOUT_AFTER_GRASP_OPEN_VALUE", "45") or 45)\n            phase1 = int(float(os.environ.get("ROLLOUT_AFTER_GRASP_HOLD_FRAMES", "30") or 30))\n            phase2 = phase1 + int(float(os.environ.get("ROLLOUT_AFTER_GRASP_LIFT_FRAMES", "60") or 60))\n            phase3 = phase2 + int(float(os.environ.get("ROLLOUT_AFTER_GRASP_MOVE_FRAMES", "60") or 60))\n            phase4 = phase3 + int(float(os.environ.get("ROLLOUT_AFTER_GRASP_LOWER_FRAMES", "45") or 45))\n            phase5 = phase4 + int(float(os.environ.get("ROLLOUT_AFTER_GRASP_RELEASE_FRAMES", "45") or 45))\n\n            if frame < phase1:\n                target = {\n                    "gripper.pos": close_g,\n                }\n                phase = "clamp"\n            elif frame < phase2:\n                target = {\n                    "shoulder_lift.pos": float(os.environ.get("ROLLOUT_MACRO_LIFT_SHOULDER_LIFT", "28") or 28),\n                    "elbow_flex.pos": float(os.environ.get("ROLLOUT_MACRO_LIFT_ELBOW_FLEX", "-40") or -40),\n                    "wrist_flex.pos": float(os.environ.get("ROLLOUT_MACRO_LIFT_WRIST_FLEX", "101") or 101),\n                    "gripper.pos": close_g,\n                }\n                phase = "lift"\n            elif frame < phase3:\n                target = {\n                    "shoulder_pan.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_SHOULDER_PAN", "0") or 0),\n                    "shoulder_lift.pos": float(os.environ.get("ROLLOUT_MACRO_LIFT_SHOULDER_LIFT", "28") or 28),\n                    "elbow_flex.pos": float(os.environ.get("ROLLOUT_MACRO_LIFT_ELBOW_FLEX", "-40") or -40),\n                    "wrist_flex.pos": float(os.environ.get("ROLLOUT_MACRO_LIFT_WRIST_FLEX", "101") or 101),\n                    "gripper.pos": close_g,\n                }\n                phase = "move"\n            elif frame < phase4:\n                target = {\n                    "shoulder_pan.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_SHOULDER_PAN", "0") or 0),\n                    "shoulder_lift.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_SHOULDER_LIFT", "45") or 45),\n                    "elbow_flex.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_ELBOW_FLEX", "-52") or -52),\n                    "wrist_flex.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_WRIST_FLEX", "100") or 100),\n                    "gripper.pos": close_g,\n                }\n                phase = "lower"\n            elif frame < phase5:\n                target = {\n                    "shoulder_pan.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_SHOULDER_PAN", "0") or 0),\n                    "shoulder_lift.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_SHOULDER_LIFT", "45") or 45),\n                    "elbow_flex.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_ELBOW_FLEX", "-52") or -52),\n                    "wrist_flex.pos": float(os.environ.get("ROLLOUT_MACRO_PLACE_WRIST_FLEX", "100") or 100),\n                    "gripper.pos": open_g,\n                }\n                phase = "release"\n            else:\n                target = {"gripper.pos": open_g}\n                phase = "done"\n\n            for key, value in target.items():\n                if key in action_dict:\n                    action_dict[key] = value\n            if os.environ.get("ROLLOUT_DEBUG_AFTER_GRASP_MACRO", "0") == "1":\n                import time\n\n                print("[AFTER GRASP MACRO]", flush=True)\n                print(f"time={time.time():.6f}", flush=True)\n                print(f"frame={frame}", flush=True)\n                print(f"phase={phase}", flush=True)\n                print(f"target={target}", flush=True)\n\n'''
if block.strip() in s:
    print('macro block already present')
elif anchor in s:
    s = s.replace(anchor, block + anchor, 1)
